pub fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    // Precondition: v is non-empty and end < v.len()
    let mut max_val = v[0];
    let mut max_idx = 0;
    for i in 1..=end {
        if v[i] > max_val {
            max_val = v[i];
            max_idx = i;
        }
    }
    (max_val, max_idx)
}

pub fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    // Precondition: v is non-empty and start < v.len()
    let mut min_val = v[start];
    let mut min_idx = start;
    for i in (start + 1)..v.len() {
        if v[i] < min_val {
            min_val = v[i];
            min_idx = i;
        }
    }
    (min_val, min_idx)
}

pub fn barrier(v: &[i32], p: usize) -> bool {
    // Precondition: v is non-empty and p < v.len()
    // If p is the last index, the condition is vacuously true
    if p + 1 >= v.len() {
        return true;
    }

    let (prefix_max, _) = find_max_in_prefix(v, p);
    let (suffix_min, _) = find_min_in_suffix(v, p + 1);
    prefix_max < suffix_min
}

